//! 🧵️ Prepared own Part21 instances retain borrowed declaration validation positions.
use super::*;
use super::domain_cursor::DomainCursor;
struct Task<'a>{before:Option<&'a V>,after:&'a V,attribute:&'static Attr,part:usize,index:usize}
#[derive(Default)]
pub(super)struct Part21DomainWork{cursor:DomainCursor,mutation:usize,part:usize,argument:usize,derive:usize,readonly:bool,active:bool,initializing:bool,checked:bool,done:bool}
impl Part21DomainWork{
 pub(super)fn clear(&mut self){self.cursor.clear();self.active=false;self.initializing=false;self.done=true;}
 fn next(&mut self){self.active=false;self.initializing=false;self.derive=0;self.readonly=false;self.argument+=1;}
 fn task<'a>(&mut self,before:&'a Part21Instance,mutations:&'a[Ifc2x3Mutation])->Result<Option<Task<'a>>,String>{let Some(mutation)=mutations.get(self.mutation)else{self.done=true;return Ok(None)};let Ifc2x3Mutation::UpsertInstance(change)=mutation else{self.mutation+=1;return Ok(None)};let after=&change.instance;if before.entities.len()!=after.entities.len(){return Err("ifc-domain-complex-draft-required".into());}if self.part==after.entities.len(){self.mutation+=1;self.part=0;self.argument=0;return Ok(None);}let(name,args)=&after.entities[self.part];let(old_name,previous)=&before.entities[self.part];if name!=old_name||name.len()>256{return Err("ifc-domain-type-draft-required".into());}let declaration=catalog::ifc2x3_catalog().entities.get(&name.to_ascii_uppercase()).ok_or("ifc-domain-entity")?;let attributes=if after.entities.len()==1{&declaration.all_attributes}else{&declaration.attributes};if args.len()<previous.len()&&args.len()<attributes.len(){return Err("ifc-domain-argument-arity".into());}if self.argument==args.len(){self.part+=1;self.argument=0;return Ok(None);}let attribute=attributes.get(self.argument).ok_or("ifc-domain-attribute")?;Ok(Some(Task{before:previous.get(self.argument),after:&args[self.argument],attribute,part:self.part,index:self.argument}))}
 pub(super)fn advance(&mut self,event:&SnapshotEditEvent,snapshot:&Ifc2x3Snapshot,mutations:&[Ifc2x3Mutation],cx:&mut semio_framework_job::StepContext<'_>)->Result<bool,semio_framework_job::OriginalTurnFailure>{if cx.is_cancelled(){return Err(err("details-cancelled").into());}if cx.should_yield(){return Ok(false);}if self.done{return Ok(true);}cx.consume_fuel(1);if !self.checked{self.checked=true;if domain_edit::draft(event){self.done=true;return Ok(true);}return Ok(false);}let Some((path,operation))=domain_edit::path(event)else{self.done=true;return Ok(true)};let mut fields=path.split('/').skip(1);if fields.next()!=Some("document")||fields.next()!=Some("instances"){self.done=true;return Ok(true);}let Some(row)=fields.next().and_then(|row|row.parse::<usize>().ok())else{self.done=true;return Ok(true)};let Some(before)=snapshot.document.instances.get(row)else{self.done=true;return Ok(true)};let Some(task)=self.task(before,mutations).map_err(err)?else{return Ok(self.done)};
 if self.active{if self.cursor.advance(catalog::ifc2x3_catalog(),task.before.unwrap_or(task.after),task.after,snapshot).map_err(err)?{self.next();}return Ok(false);}
 if !self.initializing{self.readonly=task.attribute.derived;self.derive=0;self.initializing=true;return Ok(false);}if self.derive<before.entities.len(){let name=&before.entities[self.derive].0;if name.len()<=256{if let Some(declaration)=catalog::ifc2x3_catalog().entities.get(&name.to_ascii_uppercase()){self.readonly|=declaration.all_attributes.iter().any(|other|other.derived&&other.name==task.attribute.name&&other.declared_by==task.attribute.declared_by);}}self.derive+=1;return Ok(false);}
 let prefix=format!("/document/instances/{row}/entities/{}/arguments/{}",task.part,task.index);let suffix=path.strip_prefix(&prefix).filter(|suffix|suffix.is_empty()||suffix.starts_with('/'));let mut indices=[0;128];let length=if !self.readonly{if let(Some(previous),Some(suffix))=(task.before,suffix){domain_edit::route(previous,suffix,&mut indices).map_err(err)?}else{0}}else{0};self.cursor.start(&task.attribute.type_expr,&indices[..length],operation,task.attribute.optional,task.before.is_none(),self.readonly).map_err(err)?;self.active=true;Ok(false)}
}
